/* ==========================================================================
   LEDYVAS — Contratos · texto en 5 idiomas (es / en / it / fr / pt)
   Un solo contrato: DISTRIBUIDOR OFICIAL (empresa). Membresía US$199/año,
   comisión 20%, cuota de 5 ventas en 150 días. El Distribuidor puede tener
   sus propios vendedores (los nombra avisando a Ledyvas, los paga con cargo
   a su 20%, se hace cargo de su impuesto y facturación). Ledyvas solo
   contrata con el Distribuidor. Modelo: SOLO VENDE. Ledyvas cobra al cliente,
   emite/activa/entrega la licencia, nunca sin confirmar el pago. El
   Distribuidor no toca dinero de clientes ni tiene acceso a ningún sistema.
   ⚠️ BORRADOR. Redactado para revisión de Leo + asesor legal antes de uso.
   La versión en ESPAÑOL es la que rige (ley de la República Dominicana);
   las demás son traducción de cortesía.
   Usado por contrato.html.
   ========================================================================== */
(function () {
  "use strict";

  var META = {
    es: { draft: "BORRADOR — sujeto a revisión legal. No firmar hasta que Ledyvas confirme la versión definitiva.", governs: "" },
    en: { draft: "DRAFT — subject to legal review. Do not sign until Ledyvas confirms the final version.", governs: "Courtesy translation. If there is any discrepancy, the Spanish version prevails (law of the Dominican Republic)." },
    it: { draft: "BOZZA — soggetta a revisione legale. Non firmare finché Ledyvas non conferma la versione definitiva.", governs: "Traduzione di cortesia. In caso di discrepanza prevale la versione in spagnolo (legge della Repubblica Dominicana)." },
    fr: { draft: "PROJET — sous réserve d'une révision juridique. Ne pas signer tant que Ledyvas n'a pas confirmé la version définitive.", governs: "Traduction de courtoisie. En cas de divergence, la version espagnole prévaut (droit de la République dominicaine)." },
    pt: { draft: "RASCUNHO — sujeito a revisão jurídica. Não assinar até a Ledyvas confirmar a versão definitiva.", governs: "Tradução de cortesia. Em caso de divergência, prevalece a versão em espanhol (lei da República Dominicana)." }
  };

  var TITLES = {
    distribuidor: { es: "Contrato de Distribuidor Oficial", en: "Official Distributor Agreement", it: "Contratto di Distributore Ufficiale", fr: "Contrat de Distributeur Officiel", pt: "Contrato de Distribuidor Oficial" }
  };

  var PARTIES = {
    distribuidor: {
      es: "Este contrato se celebra entre <b>Ledyvas</b> (Leonardo Cosci, RNC [pendiente], República Dominicana), en adelante “Ledyvas”, y la empresa identificada en la solicitud de distribuidor ya verificada, representada por su representante legal, en adelante “el Distribuidor”.",
      en: "This agreement is between <b>Ledyvas</b> (Leonardo Cosci, Tax ID [pending], Dominican Republic), “Ledyvas”, and the company identified in the already-verified distributor application, acting through its legal representative, “the Distributor”.",
      it: "Il presente contratto è stipulato tra <b>Ledyvas</b> (Leonardo Cosci, codice fiscale [in attesa], Repubblica Dominicana), “Ledyvas”, e l'impresa indicata nella domanda di distributore già verificata, rappresentata dal suo rappresentante legale, “il Distributore”.",
      fr: "Le présent contrat est conclu entre <b>Ledyvas</b> (Leonardo Cosci, identifiant fiscal [en attente], République dominicaine), « Ledyvas », et la société identifiée dans la demande de distributeur déjà vérifiée, agissant par son représentant légal, « le Distributeur ».",
      pt: "Este contrato é celebrado entre a <b>Ledyvas</b> (Leonardo Cosci, identificação fiscal [pendente], República Dominicana), “Ledyvas”, e a empresa identificada no pedido de distribuidor já verificado, representada pelo seu representante legal, “o Distribuidor”."
    }
  };

  // ---------------- CONTRATO DE DISTRIBUIDOR OFICIAL ----------------
  var DISTRIBUIDOR = {
    es: [
      { t: "1. Objeto y designación", b: "Ledyvas designa al Distribuidor como <b>Distribuidor Oficial</b> de Ledyvas para promover y vender el software Ledyvas a clientes finales en el territorio indicado en la solicitud verificada. El ingreso del Distribuidor proviene únicamente de comisiones por licencias vendidas a clientes finales; no recibe compensación por reclutar o incorporar a otros distribuidores o vendedores. Ledyvas no garantiza ningún nivel de ingresos." },
      { t: "2. Membresía", b: "El Distribuidor abona una membresía de <b>US$ 199</b> por un período de un (1) año, por adelantado. La membresía da derecho a: el sello “Distribuidor Oficial”; figurar en el listado de distribuidores de ledyvas.com; exclusividad en el territorio asignado (cláusula 8); la derivación de las consultas de compra que Ledyvas reciba de ese territorio sin código de un distribuidor; soporte prioritario; capacitación y certificación; y una (1) licencia de demostración de Ledyvas, no revendible, para presentar el producto a prospectos. La membresía no es reembolsable, salvo: (a) si Ledyvas no aprueba la solicitud del Distribuidor, o (b) si el Distribuidor solicita la cancelación dentro de los 14 días corridos desde la firma." },
      { t: "3. Comisión", b: "Ledyvas paga al Distribuidor una comisión del <b>20%</b> sobre el precio de lista de cada licencia vendida con su código, una sola vez por licencia. Se devenga cuando Ledyvas confirma el pago del cliente en su cuenta." },
      { t: "4. Pago de la comisión", b: "Mensual, dentro de los primeros 10 días del mes siguiente, por el método indicado por el Distribuidor. Los costos de la transferencia los asume el Distribuidor. El Distribuidor emite su propia factura a Ledyvas por la comisión, como en cualquier venta entre empresas, conforme a su normativa fiscal; Ledyvas puede condicionar el pago a la recepción de esa factura." },
      { t: "5. Cobro, entrega de la licencia y manejo de fondos", b: "Ledyvas cobra directamente al cliente. Ledyvas es el único que emite, activa y entrega la licencia, directamente al cliente, y únicamente después de confirmar el pago en su cuenta; en ningún caso se activa una licencia sin la confirmación del pago. El Distribuidor no tiene acceso al sistema de licencias, al panel de administración, a las cuentas de clientes ni a las descargas. El Distribuidor no está autorizado a recibir, retener ni administrar pagos de clientes en nombre de Ledyvas; todo pago se realiza directamente a la cuenta de Ledyvas." },
      { t: "6. Cuota de permanencia", b: "Para conservar la condición de Distribuidor Oficial, el Distribuidor debe concretar al menos cinco (5) ventas de licencias Ledyvas dentro de los primeros ciento cincuenta (150) días contados desde la finalización de la capacitación. Si no alcanza esa cuota en el plazo, el Distribuidor pierde la condición de Distribuidor Oficial por el resto del período anual: pierde el sello “Distribuidor Oficial”, el listado, la exclusividad de territorio, la derivación de consultas y la licencia de demostración, y su comisión sobre las ventas que siga concretando baja al 15%. El monto abonado por la membresía no se reembolsa y la membresía no se renueva, salvo acuerdo expreso de Ledyvas." },
      { t: "7. Incentivo por cumplimiento", b: "Al concretar las cinco (5) ventas dentro del plazo, Ledyvas entrega al Distribuidor una (1) licencia de Ledyvas Simple para su venta a un cliente final. El Distribuidor conserva íntegramente el importe de esa venta, que no puede ser inferior a US$ 500." },
      { t: "8. Territorio", b: "Mientras la membresía esté vigente y la cuota cumplida, la designación es exclusiva en el territorio indicado: Ledyvas no nombra otros Distribuidores Oficiales en ese territorio y toda venta a un cliente final de ese territorio se atribuye al Distribuidor. Dentro de su territorio, el Distribuidor puede designar sus propios vendedores para promover Ledyvas, sin necesidad de aprobación de Ledyvas: basta con comunicar a Ledyvas la lista de esos vendedores y mantenerla actualizada. Ledyvas paga la comisión de la cláusula 3 únicamente al Distribuidor, por toda venta atribuida a él o a su territorio, la haya cerrado el Distribuidor o uno de sus vendedores. El Distribuidor retribuye a sus vendedores según lo que acuerde con cada uno, con cargo a su propia comisión, y es el único responsable de su relación con ellos, de su remuneración, de sus impuestos y de su facturación; esos vendedores no tienen relación contractual con Ledyvas ni derecho a reclamarle pago alguno. Ledyvas conserva el derecho de vender directamente en cualquier territorio." },
      { t: "9. Reembolsos y contracargos", b: "Si un cliente obtiene un reembolso o hace un contracargo, la comisión de esa venta se anula. Si ya fue pagada, se descuenta de liquidaciones futuras." },
      { t: "10. Atribución de la venta", b: "La venta se atribuye al Distribuidor cuyo código acompañó al cliente al momento de la compra, o a las consultas entrantes de su territorio conforme a la cláusula 2. Ledyvas resuelve de buena fe cualquier disputa de atribución y su decisión es final." },
      { t: "11. Uso de la marca", b: "El Distribuidor puede identificarse como “Distribuidor Oficial de Ledyvas” y usar el kit de marca que Ledyvas provea, únicamente para promover Ledyvas y mientras conserve esa condición. No puede registrar marcas, nombres comerciales ni dominios que contengan “Ledyvas” o sean confundibles. Al perder la condición de Distribuidor Oficial o al terminar el contrato, cesa todo uso de la marca en 5 días." },
      { t: "12. Obligaciones del Distribuidor", b: "Presentar el producto con fidelidad y sin promesas falsas ni garantías de ingresos a terceros; mantener al menos una persona capacitada y certificada en Ledyvas; ser el primer nivel de atención comercial de sus clientes (presentación, demostración, acompañamiento), derivando a Ledyvas las consultas técnicas; no realizar ingeniería inversa ni sublicenciar el software; cumplir la política comercial y de marca que Ledyvas comunique por escrito." },
      { t: "13. Soporte y actualizaciones", b: "Ledyvas provee el software, las actualizaciones y todo el soporte técnico y la atención al cliente. Ledyvas puede ofrecer formación al personal del Distribuidor." },
      { t: "14. Confidencialidad", b: "Cada parte protege la información no pública de la otra: precios especiales, datos de clientes, hoja de ruta del producto, cifras y condiciones del programa. La obligación sobrevive a la terminación." },
      { t: "15. Protección de datos y cumplimiento fiscal", b: "Los datos de prospectos y clientes que el Distribuidor recopile se usan solo para vender Ledyvas y se comparten con Ledyvas, responsable del tratamiento. Cada parte cumple sus obligaciones fiscales en su país; el Distribuidor declara la comisión como ingreso propio y no representa a Ledyvas ante autoridades sin autorización expresa." },
      { t: "16. Duración y terminación", b: "El contrato tiene una duración estricta de un (1) año desde su firma y no se renueva de forma automática. Al finalizar el período, Ledyvas evaluará el rendimiento del Distribuidor y se reserva el derecho de modificar el precio de la membresía, los porcentajes de comisión y los términos generales para el siguiente período anual; sesenta (60) días antes del vencimiento comunicará si ofrece renovación y con qué términos. Como referencia del criterio de rendimiento: si el Distribuidor concretó quince (15) o más ventas de licencias en el período, Ledyvas le ofrece la renovación con la membresía bonificada, sin cargo; si no concretó ninguna venta en el período, el contrato termina automáticamente al vencimiento y el código se desactiva sin necesidad de aviso; en los casos intermedios, Ledyvas ofrece la renovación al precio de membresía vigente en ese momento. Cualquiera de las partes puede terminar antes con 30 días de aviso por escrito, sin causa. Ledyvas puede terminar de inmediato por incumplimiento de las cláusulas 5, 11 o 12. A la terminación, el Distribuidor deja de usar la marca y de vender; las licencias ya vendidas a clientes finales siguen válidas y con soporte de Ledyvas; las comisiones ya devengadas y no revertidas se pagan a la tasa original." },
      { t: "17. Sin sociedad ni relación laboral", b: "Este contrato no crea sociedad, franquicia, agencia con poder de representación ni relación laboral. El Distribuidor puede distribuir otros productos, incluso de la competencia, salvo pacto expreso en contrario." },
      { t: "18. Ley aplicable y disputas", b: "Este contrato se rige por el derecho de la República Dominicana, en particular por el Código Civil, el Código de Comercio y la Ley núm. 126-02 sobre Comercio Electrónico, Documentos y Firmas Digitales. Se excluye de forma expresa la aplicación de la Convención de las Naciones Unidas sobre los Contratos de Compraventa Internacional de Mercaderías (Viena, 1980). Las partes intentarán resolver de buena fe cualquier diferencia; de no lograrlo, se someten de forma exclusiva a los tribunales competentes de la República Dominicana, con renuncia expresa a cualquier otro fuero o jurisdicción que pudiera corresponderles, cualquiera sea el domicilio o la nacionalidad de la otra parte." },
      { t: "19. Firma electrónica", b: "Al marcar la casilla de aceptación y escribir el nombre completo del representante legal, el Distribuidor manifiesta su consentimiento y firma este contrato en los términos de la Ley núm. 126-02 sobre Comercio Electrónico, Documentos y Firmas Digitales, con el mismo valor legal que una firma manuscrita. Ledyvas registra la fecha, la hora y la dirección IP de la firma como constancia." }
    ],
    en: [
      { t: "1. Purpose and appointment", b: "Ledyvas appoints the Distributor as an <b>Official Distributor</b> of Ledyvas, to promote and sell the Ledyvas software to end customers in the territory stated in the verified application. The Distributor's income comes solely from commission on licenses sold to end customers; it receives no compensation for recruiting or onboarding other distributors or salespeople. Ledyvas guarantees no level of income." },
      { t: "2. Membership", b: "The Distributor pays a membership fee of <b>US$ 199</b> for a one (1) year period, in advance. Membership grants: the “Official Distributor” badge; a listing in the distributor directory on ledyvas.com; exclusivity in the assigned territory (clause 8); routing of purchase enquiries Ledyvas receives from that territory without a distributor's code; priority support; training and certification; and one (1) non-resellable Ledyvas demo license to present the product to prospects. The membership fee is non-refundable, except: (a) if Ledyvas does not approve the Distributor's application, or (b) if the Distributor requests cancellation within 14 calendar days of signature." },
      { t: "3. Commission", b: "Ledyvas pays the Distributor a <b>20%</b> commission on the list price of each license sold with its code, once per license. Earned when Ledyvas confirms the customer's payment in its account." },
      { t: "4. Commission payment", b: "Monthly, within the first 10 days of the following month, by the method the Distributor specified. Transfer fees are borne by the Distributor. The Distributor issues its own invoice to Ledyvas for the commission, as in any business-to-business sale, in accordance with its tax rules; Ledyvas may make payment conditional on receipt of that invoice." },
      { t: "5. Collection, license delivery and handling of funds", b: "Ledyvas collects payment directly from the customer. Ledyvas is the only party that issues, activates and delivers the license, directly to the customer, and only after confirming payment in its account; a license is never activated without payment confirmation. The Distributor has no access to the licensing system, the admin panel, customer accounts or downloads. The Distributor is not authorized to receive, hold or handle customer payments on behalf of Ledyvas; all payment goes directly to Ledyvas's account." },
      { t: "6. Performance quota", b: "To keep Official Distributor status, the Distributor must close at least five (5) Ledyvas license sales within the first one hundred and fifty (150) days from completion of training. If it does not meet that quota within the period, the Distributor loses Official Distributor status for the rest of the annual term: it loses the “Official Distributor” badge, the listing, territory exclusivity, enquiry routing and the demo license, and its commission on any further sales drops to 15%. The membership fee paid is not refunded and the membership is not renewed, save express agreement by Ledyvas." },
      { t: "7. Achievement incentive", b: "On closing the five (5) sales within the period, Ledyvas gives the Distributor one (1) Ledyvas Simple license to sell to an end customer. The Distributor keeps the full proceeds of that sale, which may not be below US$ 500." },
      { t: "8. Territory", b: "While the membership is active and the quota is met, the appointment is exclusive in the stated territory: Ledyvas will not appoint other Official Distributors there, and any sale to an end customer in that territory is attributed to the Distributor. Within its territory, the Distributor may appoint its own salespeople to promote Ledyvas, without Ledyvas's approval: it is enough to send Ledyvas the list of those salespeople and keep it up to date. Ledyvas pays the clause 3 commission solely to the Distributor, for every sale attributed to it or to its territory, whether closed by the Distributor or by one of its salespeople. The Distributor pays its salespeople as it agrees with each of them, out of its own commission, and is solely responsible for its relationship with them, their remuneration, their taxes and their invoicing; those salespeople have no contractual relationship with Ledyvas and no right to claim any payment from it. Ledyvas keeps the right to sell directly in any territory." },
      { t: "9. Refunds and chargebacks", b: "If a customer obtains a refund or files a chargeback, the commission for that sale is cancelled. If already paid, it is deducted from future settlements." },
      { t: "10. Sale attribution", b: "A sale is attributed to the Distributor whose code accompanied the customer at purchase, or to inbound enquiries from its territory under clause 2. Ledyvas resolves any attribution dispute in good faith and its decision is final." },
      { t: "11. Use of the brand", b: "The Distributor may identify itself as an “Official Distributor of Ledyvas” and use the brand kit Ledyvas provides, solely to promote Ledyvas and while it holds that status. It may not register trademarks, trade names or domains containing “Ledyvas” or likely to be confused with it. On losing Official Distributor status or on termination, all use of the brand stops within 5 days." },
      { t: "12. Distributor obligations", b: "Present the product faithfully, without false promises or income guarantees to third parties; keep at least one person trained and certified on Ledyvas; be the first level of commercial contact for its customers (presentation, demonstration, follow-up), escalating technical questions to Ledyvas; not reverse-engineer or sublicense the software; follow the commercial and brand policy Ledyvas communicates in writing." },
      { t: "13. Support and updates", b: "Ledyvas provides the software, updates and all technical support and customer service. Ledyvas may train the Distributor's staff." },
      { t: "14. Confidentiality", b: "Each party protects the other's non-public information: special pricing, customer data, product roadmap, figures and program terms. The obligation survives termination." },
      { t: "15. Data protection and tax compliance", b: "Prospect and customer data the Distributor collects is used only to sell Ledyvas and is shared with Ledyvas, the data controller. Each party meets its tax obligations in its country; the Distributor declares the commission as its own income and does not represent Ledyvas before authorities without express authorization." },
      { t: "16. Term and termination", b: "The agreement has a strict term of one (1) year from signature and does not renew automatically. At the end of the period, Ledyvas will assess the Distributor's performance and reserves the right to change the membership price, the commission rates and the general terms for the next annual period; sixty (60) days before expiry it will state whether it offers renewal and on what terms. As a reference for the performance criterion: if the Distributor closed fifteen (15) or more license sales in the period, Ledyvas offers renewal with the membership fee waived, at no cost; if it closed no sales in the period, the agreement ends automatically at expiry and the code is deactivated without notice; in between, Ledyvas offers renewal at the membership price then in force. Either party may terminate earlier on 30 days' written notice, without cause. Ledyvas may terminate immediately for breach of clauses 5, 11 or 12. On termination, the Distributor stops using the brand and selling; licenses already sold to end customers stay valid and supported by Ledyvas; commissions already earned and not reversed are paid at the original rate." },
      { t: "17. No partnership, no employment", b: "This agreement creates no partnership, franchise, agency with power of representation or employment. The Distributor may distribute other products, including competitors', unless expressly agreed otherwise." },
      { t: "18. Governing law and disputes", b: "This agreement is governed by the law of the Dominican Republic, in particular its Civil Code, its Commercial Code and Law No. 126-02 on Electronic Commerce, Documents and Digital Signatures. The application of the United Nations Convention on Contracts for the International Sale of Goods (Vienna, 1980) is expressly excluded. The parties will try to resolve any disagreement in good faith; failing that, they submit exclusively to the competent courts of the Dominican Republic, expressly waiving any other venue or jurisdiction that might otherwise apply, whatever the domicile or nationality of the other party." },
      { t: "19. Electronic signature", b: "By checking the acceptance box and typing the legal representative's full name, the Distributor gives consent and signs this agreement under Law No. 126-02 on Electronic Commerce, Documents and Digital Signatures, with the same legal force as a handwritten signature. Ledyvas records the date, time and IP address as evidence." }
    ],
    it: [
      { t: "1. Oggetto e nomina", b: "Ledyvas nomina il Distributore come <b>Distributore Ufficiale</b> di Ledyvas, per promuovere e vendere il software Ledyvas a clienti finali nel territorio indicato nella domanda verificata. Il reddito del Distributore deriva unicamente dalle commissioni sulle licenze vendute a clienti finali; non riceve compensi per il reclutamento o l'inserimento di altri distributori o venditori. Ledyvas non garantisce alcun livello di reddito." },
      { t: "2. Adesione", b: "Il Distributore versa una quota di adesione di <b>US$ 199</b> per un periodo di un (1) anno, in anticipo. L'adesione dà diritto a: il marchio “Distributore Ufficiale”; la presenza nell'elenco distributori di ledyvas.com; l'esclusiva nel territorio assegnato (clausola 8); l'inoltro delle richieste d'acquisto che Ledyvas riceve da quel territorio senza il codice di un distributore; assistenza prioritaria; formazione e certificazione; e una (1) licenza dimostrativa di Ledyvas, non rivendibile, per presentare il prodotto ai potenziali clienti. La quota non è rimborsabile, salvo: (a) se Ledyvas non approva la domanda del Distributore, o (b) se il Distributore chiede l'annullamento entro 14 giorni di calendario dalla firma." },
      { t: "3. Commissione", b: "Ledyvas riconosce al Distributore una commissione del <b>20%</b> sul prezzo di listino di ogni licenza venduta con il suo codice, una sola volta per licenza. Matura quando Ledyvas conferma il pagamento del cliente sul proprio conto." },
      { t: "4. Pagamento della commissione", b: "Mensile, entro i primi 10 giorni del mese successivo, con il metodo indicato dal Distributore. I costi del trasferimento sono a carico del Distributore. Il Distributore emette la propria fattura a Ledyvas per la commissione, come in qualsiasi vendita tra imprese, secondo la propria normativa fiscale; Ledyvas può subordinare il pagamento alla ricezione di tale fattura." },
      { t: "5. Incasso, consegna della licenza e gestione dei fondi", b: "Ledyvas incassa direttamente dal cliente. Ledyvas è l'unico soggetto che emette, attiva e consegna la licenza, direttamente al cliente, e solo dopo aver confermato il pagamento sul proprio conto; in nessun caso una licenza viene attivata senza la conferma del pagamento. Il Distributore non ha accesso al sistema delle licenze, al pannello di amministrazione, agli account dei clienti né ai download. Il Distributore non è autorizzato a ricevere, trattenere o gestire pagamenti dei clienti per conto di Ledyvas; ogni pagamento viene effettuato direttamente sul conto di Ledyvas." },
      { t: "6. Quota di permanenza", b: "Per mantenere lo status di Distributore Ufficiale, il Distributore deve concludere almeno cinque (5) vendite di licenze Ledyvas entro i primi centocinquanta (150) giorni dalla fine della formazione. Se non raggiunge tale quota nel termine, il Distributore perde lo status di Distributore Ufficiale per il resto del periodo annuale: perde il marchio “Distributore Ufficiale”, l'inserimento nell'elenco, l'esclusiva territoriale, l'inoltro delle richieste e la licenza dimostrativa, e la sua commissione sulle vendite che continua a concludere scende al 15%. La quota di adesione versata non viene rimborsata e l'adesione non viene rinnovata, salvo accordo espresso di Ledyvas." },
      { t: "7. Incentivo al raggiungimento", b: "Al raggiungimento delle cinque (5) vendite entro il termine, Ledyvas consegna al Distributore una (1) licenza di Ledyvas Simple da vendere a un cliente finale. Il Distributore trattiene integralmente l'importo di tale vendita, che non può essere inferiore a US$ 500." },
      { t: "8. Territorio", b: "Finché l'adesione è attiva e la quota è rispettata, la nomina è esclusiva nel territorio indicato: Ledyvas non nomina altri Distributori Ufficiali in quel territorio e ogni vendita a un cliente finale di quel territorio è attribuita al Distributore. Nel proprio territorio, il Distributore può nominare i propri venditori per promuovere Ledyvas, senza approvazione di Ledyvas: è sufficiente comunicare a Ledyvas l'elenco di tali venditori e mantenerlo aggiornato. Ledyvas paga la commissione della clausola 3 unicamente al Distributore, per ogni vendita attribuita a lui o al suo territorio, conclusa dal Distributore o da un suo venditore. Il Distributore retribuisce i propri venditori secondo quanto concordato con ciascuno, a carico della propria commissione, ed è l'unico responsabile del rapporto con loro, della loro remunerazione, delle loro imposte e della loro fatturazione; tali venditori non hanno alcun rapporto contrattuale con Ledyvas né diritto a reclamarle alcun pagamento. Ledyvas conserva il diritto di vendere direttamente in qualsiasi territorio." },
      { t: "9. Rimborsi e storni", b: "Se un cliente ottiene un rimborso o effettua uno storno, la commissione di quella vendita è annullata. Se già pagata, viene detratta dalle liquidazioni future." },
      { t: "10. Attribuzione della vendita", b: "La vendita è attribuita al Distributore il cui codice ha accompagnato il cliente all'acquisto, o alle richieste in arrivo dal suo territorio ai sensi della clausola 2. Ledyvas risolve in buona fede ogni controversia di attribuzione e la sua decisione è definitiva." },
      { t: "11. Uso del marchio", b: "Il Distributore può identificarsi come “Distributore Ufficiale di Ledyvas” e usare il kit di marchio fornito da Ledyvas, solo per promuovere Ledyvas e finché mantiene tale status. Non può registrare marchi, nomi commerciali o domini contenenti “Ledyvas” o confondibili. Alla perdita dello status di Distributore Ufficiale o alla cessazione del contratto, ogni uso del marchio cessa entro 5 giorni." },
      { t: "12. Obblighi del Distributore", b: "Presentare il prodotto con fedeltà, senza false promesse né garanzie di reddito a terzi; mantenere almeno una persona formata e certificata su Ledyvas; essere il primo livello di contatto commerciale dei propri clienti (presentazione, dimostrazione, accompagnamento), inoltrando a Ledyvas le richieste tecniche; non fare reverse engineering né concedere sottolicenze del software; rispettare la politica commerciale e di marchio comunicata da Ledyvas per iscritto." },
      { t: "13. Assistenza e aggiornamenti", b: "Ledyvas fornisce il software, gli aggiornamenti e tutta l'assistenza tecnica e il servizio clienti. Ledyvas può formare il personale del Distributore." },
      { t: "14. Riservatezza", b: "Ogni parte protegge le informazioni non pubbliche dell'altra: prezzi speciali, dati dei clienti, roadmap del prodotto, cifre e condizioni del programma. L'obbligo sopravvive alla cessazione." },
      { t: "15. Protezione dei dati e conformità fiscale", b: "I dati di potenziali clienti e clienti raccolti dal Distributore sono usati solo per vendere Ledyvas e condivisi con Ledyvas, titolare del trattamento. Ogni parte adempie i propri obblighi fiscali nel proprio paese; il Distributore dichiara la commissione come reddito proprio e non rappresenta Ledyvas davanti alle autorità senza autorizzazione espressa." },
      { t: "16. Durata e cessazione", b: "Il contratto ha una durata rigorosa di un (1) anno dalla firma e non si rinnova automaticamente. Alla fine del periodo, Ledyvas valuterà il rendimento del Distributore e si riserva il diritto di modificare il prezzo dell'adesione, le percentuali di commissione e i termini generali per il periodo annuale successivo; sessanta (60) giorni prima della scadenza comunicherà se offre il rinnovo e a quali condizioni. Come riferimento del criterio di rendimento: se il Distributore ha concluso quindici (15) o più vendite di licenze nel periodo, Ledyvas offre il rinnovo con la quota di adesione azzerata, senza costi; se non ha concluso alcuna vendita nel periodo, il contratto termina automaticamente alla scadenza e il codice viene disattivato senza necessità di preavviso; nei casi intermedi, Ledyvas offre il rinnovo al prezzo di adesione vigente in quel momento. Ciascuna parte può recedere prima con preavviso scritto di 30 giorni, senza motivo. Ledyvas può risolvere immediatamente per violazione delle clausole 5, 11 o 12. Alla cessazione, il Distributore smette di usare il marchio e di vendere; le licenze già vendute ai clienti finali restano valide e assistite da Ledyvas; le commissioni già maturate e non stornate sono pagate alla tariffa originale." },
      { t: "17. Nessuna società né rapporto di lavoro", b: "Questo contratto non crea società, franchising, agenzia con potere di rappresentanza né rapporto di lavoro. Il Distributore può distribuire altri prodotti, anche concorrenti, salvo patto contrario espresso." },
      { t: "18. Legge applicabile e controversie", b: "Il presente contratto è regolato dal diritto della Repubblica Dominicana, in particolare dal Codice Civile, dal Codice di Commercio e dalla Legge n. 126-02 sul Commercio Elettronico, Documenti e Firme Digitali. È espressamente esclusa l'applicazione della Convenzione delle Nazioni Unite sui contratti di compravendita internazionale di merci (Vienna, 1980). Le parti cercheranno di risolvere in buona fede ogni divergenza; in mancanza, si sottopongono in via esclusiva ai tribunali competenti della Repubblica Dominicana, rinunciando espressamente a qualsiasi altro foro o giurisdizione eventualmente competente, qualunque sia il domicilio o la nazionalità dell'altra parte." },
      { t: "19. Firma elettronica", b: "Selezionando la casella di accettazione e digitando il nome completo del rappresentante legale, il Distributore presta il consenso e firma il presente contratto ai sensi della Legge n. 126-02 sul Commercio Elettronico, Documenti e Firme Digitali, con lo stesso valore legale di una firma autografa. Ledyvas registra data, ora e indirizzo IP come prova." }
    ],
    fr: [
      { t: "1. Objet et désignation", b: "Ledyvas désigne le Distributeur comme <b>Distributeur Officiel</b> de Ledyvas, pour promouvoir et vendre le logiciel Ledyvas auprès de clients finaux sur le territoire indiqué dans la demande vérifiée. Les revenus du Distributeur proviennent uniquement des commissions sur les licences vendues à des clients finaux ; il ne reçoit aucune rémunération pour le recrutement ou l'intégration d'autres distributeurs ou vendeurs. Ledyvas ne garantit aucun niveau de revenu." },
      { t: "2. Adhésion", b: "Le Distributeur paie une adhésion de <b>199 US$</b> pour une période d'un (1) an, d'avance. L'adhésion donne droit à : le label « Distributeur Officiel » ; une inscription dans l'annuaire des distributeurs sur ledyvas.com ; l'exclusivité sur le territoire attribué (clause 8) ; l'acheminement des demandes d'achat que Ledyvas reçoit de ce territoire sans le code d'un distributeur ; un support prioritaire ; une formation et une certification ; et une (1) licence de démonstration Ledyvas, non revendable, pour présenter le produit aux prospects. L'adhésion n'est pas remboursable, sauf : (a) si Ledyvas n'approuve pas la demande du Distributeur, ou (b) si le Distributeur demande l'annulation dans les 14 jours calendaires suivant la signature." },
      { t: "3. Commission", b: "Ledyvas verse au Distributeur une commission de <b>20 %</b> sur le prix catalogue de chaque licence vendue avec son code, une seule fois par licence. Acquise lorsque Ledyvas confirme le paiement du client sur son compte." },
      { t: "4. Paiement de la commission", b: "Mensuel, dans les 10 premiers jours du mois suivant, par le moyen indiqué par le Distributeur. Les frais de transfert sont à la charge du Distributeur. Le Distributeur émet sa propre facture à Ledyvas pour la commission, comme pour toute vente entre entreprises, conformément à ses règles fiscales ; Ledyvas peut conditionner le paiement à la réception de cette facture." },
      { t: "5. Encaissement, remise de la licence et gestion des fonds", b: "Ledyvas encaisse directement auprès du client. Ledyvas est le seul à émettre, activer et remettre la licence, directement au client, et uniquement après confirmation du paiement sur son compte ; en aucun cas une licence n'est activée sans confirmation du paiement. Le Distributeur n'a accès ni au système de licences, ni au panneau d'administration, ni aux comptes clients, ni aux téléchargements. Le Distributeur n'est pas autorisé à recevoir, détenir ou gérer des paiements de clients pour le compte de Ledyvas ; tout paiement est effectué directement sur le compte de Ledyvas." },
      { t: "6. Quota de maintien", b: "Pour conserver le statut de Distributeur Officiel, le Distributeur doit conclure au moins cinq (5) ventes de licences Ledyvas dans les cent cinquante (150) premiers jours à compter de la fin de la formation. S'il n'atteint pas ce quota dans le délai, le Distributeur perd le statut de Distributeur Officiel pour le reste de la période annuelle : il perd le label « Distributeur Officiel », l'inscription, l'exclusivité territoriale, l'acheminement des demandes et la licence de démonstration, et sa commission sur les ventes qu'il continue de conclure passe à 15 %. Le montant de l'adhésion versé n'est pas remboursé et l'adhésion n'est pas renouvelée, sauf accord exprès de Ledyvas." },
      { t: "7. Prime de réalisation", b: "En concluant les cinq (5) ventes dans le délai, Ledyvas remet au Distributeur une (1) licence Ledyvas Simple à vendre à un client final. Le Distributeur conserve l'intégralité du produit de cette vente, qui ne peut être inférieur à 500 US$." },
      { t: "8. Territoire", b: "Tant que l'adhésion est active et le quota atteint, la désignation est exclusive sur le territoire indiqué : Ledyvas ne nomme pas d'autres Distributeurs Officiels sur ce territoire et toute vente à un client final de ce territoire est attribuée au Distributeur. Sur son territoire, le Distributeur peut désigner ses propres vendeurs pour promouvoir Ledyvas, sans l'approbation de Ledyvas : il suffit de communiquer à Ledyvas la liste de ces vendeurs et de la tenir à jour. Ledyvas verse la commission de la clause 3 uniquement au Distributeur, pour toute vente attribuée à lui ou à son territoire, conclue par le Distributeur ou par l'un de ses vendeurs. Le Distributeur rémunère ses vendeurs selon ce qu'il convient avec chacun, sur sa propre commission, et il est seul responsable de sa relation avec eux, de leur rémunération, de leurs impôts et de leur facturation ; ces vendeurs n'ont aucune relation contractuelle avec Ledyvas ni aucun droit de lui réclamer un paiement. Ledyvas conserve le droit de vendre directement sur tout territoire." },
      { t: "9. Remboursements et rétrofacturations", b: "Si un client obtient un remboursement ou effectue une rétrofacturation, la commission de cette vente est annulée. Si elle a déjà été versée, elle est déduite des règlements futurs." },
      { t: "10. Attribution de la vente", b: "Une vente est attribuée au Distributeur dont le code accompagnait le client à l'achat, ou aux demandes entrantes de son territoire au titre de la clause 2. Ledyvas tranche tout litige d'attribution de bonne foi et sa décision est définitive." },
      { t: "11. Utilisation de la marque", b: "Le Distributeur peut se présenter comme « Distributeur Officiel de Ledyvas » et utiliser le kit de marque fourni par Ledyvas, uniquement pour promouvoir Ledyvas et tant qu'il conserve ce statut. Il ne peut pas enregistrer de marques, noms commerciaux ou domaines contenant « Ledyvas » ou prêtant à confusion. À la perte du statut de Distributeur Officiel ou à la fin du contrat, tout usage de la marque cesse sous 5 jours." },
      { t: "12. Obligations du Distributeur", b: "Présenter le produit fidèlement, sans fausses promesses ni garanties de revenus à des tiers ; disposer d'au moins une personne formée et certifiée sur Ledyvas ; être le premier niveau de contact commercial de ses clients (présentation, démonstration, accompagnement), en transmettant à Ledyvas les questions techniques ; ne pas faire d'ingénierie inverse ni de sous-licence du logiciel ; respecter la politique commerciale et de marque communiquée par écrit par Ledyvas." },
      { t: "13. Support et mises à jour", b: "Ledyvas fournit le logiciel, les mises à jour et tout le support technique et le service client. Ledyvas peut former le personnel du Distributeur." },
      { t: "14. Confidentialité", b: "Chaque partie protège les informations non publiques de l'autre : tarifs spéciaux, données clients, feuille de route produit, chiffres et conditions du programme. L'obligation subsiste après la fin du contrat." },
      { t: "15. Protection des données et conformité fiscale", b: "Les données de prospects et de clients collectées par le Distributeur ne servent qu'à vendre Ledyvas et sont partagées avec Ledyvas, responsable du traitement. Chaque partie remplit ses obligations fiscales dans son pays ; le Distributeur déclare la commission comme son propre revenu et ne représente pas Ledyvas devant les autorités sans autorisation expresse." },
      { t: "16. Durée et résiliation", b: "Le contrat a une durée stricte d'un (1) an à compter de la signature et ne se renouvelle pas automatiquement. À la fin de la période, Ledyvas évaluera la performance du Distributeur et se réserve le droit de modifier le prix de l'adhésion, les taux de commission et les conditions générales pour la période annuelle suivante ; soixante (60) jours avant l'échéance, il indiquera s'il propose un renouvellement et à quelles conditions. À titre de référence du critère de performance : si le Distributeur a conclu quinze (15) ventes de licences ou plus sur la période, Ledyvas propose le renouvellement avec l'adhésion offerte, sans frais ; s'il n'a conclu aucune vente sur la période, le contrat prend fin automatiquement à l'échéance et le code est désactivé sans préavis ; entre les deux, Ledyvas propose le renouvellement au prix d'adhésion alors en vigueur. Chaque partie peut résilier plus tôt moyennant un préavis écrit de 30 jours, sans motif. Ledyvas peut résilier immédiatement en cas de manquement aux clauses 5, 11 ou 12. À la résiliation, le Distributeur cesse d'utiliser la marque et de vendre ; les licences déjà vendues aux clients finaux restent valides et prises en charge par Ledyvas ; les commissions déjà acquises et non annulées sont payées au taux initial." },
      { t: "17. Ni société ni contrat de travail", b: "Ce contrat ne crée aucune société, franchise, agence avec pouvoir de représentation ni relation de travail. Le Distributeur peut distribuer d'autres produits, y compris concurrents, sauf accord exprès contraire." },
      { t: "18. Droit applicable et litiges", b: "Le présent contrat est régi par le droit de la République dominicaine, en particulier son Code civil, son Code de commerce et la Loi n° 126-02 sur le commerce électronique, les documents et les signatures numériques. L'application de la Convention des Nations Unies sur les contrats de vente internationale de marchandises (Vienne, 1980) est expressément exclue. Les parties s'efforceront de résoudre tout différend de bonne foi ; à défaut, elles se soumettent exclusivement aux tribunaux compétents de la République dominicaine, en renonçant expressément à tout autre for ou juridiction susceptible de s'appliquer, quel que soit le domicile ou la nationalité de l'autre partie." },
      { t: "19. Signature électronique", b: "En cochant la case d'acceptation et en saisissant le nom complet du représentant légal, le Distributeur donne son consentement et signe le présent contrat au titre de la Loi n° 126-02 sur le commerce électronique, les documents et les signatures numériques, avec la même valeur juridique qu'une signature manuscrite. Ledyvas enregistre la date, l'heure et l'adresse IP comme preuve." }
    ],
    pt: [
      { t: "1. Objeto e nomeação", b: "A Ledyvas nomeia o Distribuidor como <b>Distribuidor Oficial</b> da Ledyvas, para promover e vender o software Ledyvas a clientes finais no território indicado no pedido verificado. O rendimento do Distribuidor provém unicamente de comissões sobre licenças vendidas a clientes finais; não recebe compensação por recrutar ou integrar outros distribuidores ou vendedores. A Ledyvas não garante qualquer nível de rendimento." },
      { t: "2. Adesão", b: "O Distribuidor paga uma adesão de <b>US$ 199</b> por um período de um (1) ano, antecipadamente. A adesão dá direito a: o selo “Distribuidor Oficial”; constar na lista de distribuidores de ledyvas.com; exclusividade no território atribuído (cláusula 8); o encaminhamento das consultas de compra que a Ledyvas receba desse território sem o código de um distribuidor; suporte prioritário; formação e certificação; e uma (1) licença de demonstração da Ledyvas, não revendável, para apresentar o produto a potenciais clientes. A adesão não é reembolsável, salvo: (a) se a Ledyvas não aprovar o pedido do Distribuidor, ou (b) se o Distribuidor pedir o cancelamento no prazo de 14 dias corridos desde a assinatura." },
      { t: "3. Comissão", b: "A Ledyvas paga ao Distribuidor uma comissão de <b>20%</b> sobre o preço de tabela de cada licença vendida com o seu código, uma única vez por licença. Vence-se quando a Ledyvas confirma o pagamento do cliente na sua conta." },
      { t: "4. Pagamento da comissão", b: "Mensal, nos primeiros 10 dias do mês seguinte, pelo método indicado pelo Distribuidor. Os custos da transferência são do Distribuidor. O Distribuidor emite a sua própria fatura à Ledyvas pela comissão, como em qualquer venda entre empresas, conforme a sua normativa fiscal; a Ledyvas pode condicionar o pagamento à receção dessa fatura." },
      { t: "5. Cobrança, entrega da licença e gestão de fundos", b: "A Ledyvas cobra diretamente ao cliente. A Ledyvas é a única que emite, ativa e entrega a licença, diretamente ao cliente, e apenas depois de confirmar o pagamento na sua conta; em nenhum caso uma licença é ativada sem a confirmação do pagamento. O Distribuidor não tem acesso ao sistema de licenças, ao painel de administração, às contas de clientes nem às descargas. O Distribuidor não está autorizado a receber, reter ou administrar pagamentos de clientes em nome da Ledyvas; todo o pagamento é feito diretamente para a conta da Ledyvas." },
      { t: "6. Quota de permanência", b: "Para conservar o estatuto de Distribuidor Oficial, o Distribuidor deve concretizar pelo menos cinco (5) vendas de licenças Ledyvas nos primeiros cento e cinquenta (150) dias a contar do fim da formação. Se não atingir essa quota no prazo, o Distribuidor perde o estatuto de Distribuidor Oficial pelo resto do período anual: perde o selo “Distribuidor Oficial”, a listagem, a exclusividade de território, o encaminhamento de consultas e a licença de demonstração, e a sua comissão sobre as vendas que continue a concretizar baixa para 15%. O valor da adesão pago não é reembolsado e a adesão não é renovada, salvo acordo expresso da Ledyvas." },
      { t: "7. Incentivo por cumprimento", b: "Ao concretizar as cinco (5) vendas no prazo, a Ledyvas entrega ao Distribuidor uma (1) licença de Ledyvas Simple para venda a um cliente final. O Distribuidor conserva integralmente o valor dessa venda, que não pode ser inferior a US$ 500." },
      { t: "8. Território", b: "Enquanto a adesão estiver ativa e a quota cumprida, a nomeação é exclusiva no território indicado: a Ledyvas não nomeia outros Distribuidores Oficiais nesse território e toda a venda a um cliente final desse território é atribuída ao Distribuidor. Dentro do seu território, o Distribuidor pode designar os seus próprios vendedores para promover o Ledyvas, sem necessidade de aprovação da Ledyvas: basta comunicar à Ledyvas a lista desses vendedores e mantê-la atualizada. A Ledyvas paga a comissão da cláusula 3 unicamente ao Distribuidor, por toda a venda atribuída a ele ou ao seu território, fechada pelo Distribuidor ou por um dos seus vendedores. O Distribuidor remunera os seus vendedores conforme acordar com cada um, a cargo da sua própria comissão, e é o único responsável pela relação com eles, pela sua remuneração, pelos seus impostos e pela sua faturação; esses vendedores não têm relação contratual com a Ledyvas nem direito a reclamar-lhe qualquer pagamento. A Ledyvas conserva o direito de vender diretamente em qualquer território." },
      { t: "9. Reembolsos e estornos", b: "Se um cliente obtiver um reembolso ou fizer um estorno, a comissão dessa venda é anulada. Se já tiver sido paga, é descontada de liquidações futuras." },
      { t: "10. Atribuição da venda", b: "A venda é atribuída ao Distribuidor cujo código acompanhou o cliente na compra, ou às consultas recebidas do seu território nos termos da cláusula 2. A Ledyvas resolve qualquer disputa de atribuição de boa-fé e a sua decisão é definitiva." },
      { t: "11. Uso da marca", b: "O Distribuidor pode identificar-se como “Distribuidor Oficial da Ledyvas” e usar o kit de marca fornecido pela Ledyvas, apenas para promover a Ledyvas e enquanto mantiver esse estatuto. Não pode registar marcas, nomes comerciais nem domínios que contenham “Ledyvas” ou se confundam com ela. Ao perder o estatuto de Distribuidor Oficial ou ao terminar o contrato, todo o uso da marca cessa em 5 dias." },
      { t: "12. Obrigações do Distribuidor", b: "Apresentar o produto com fidelidade, sem falsas promessas nem garantias de rendimento a terceiros; manter pelo menos uma pessoa formada e certificada em Ledyvas; ser o primeiro nível de contacto comercial dos seus clientes (apresentação, demonstração, acompanhamento), encaminhando à Ledyvas as questões técnicas; não fazer engenharia inversa nem sublicenciar o software; cumprir a política comercial e de marca comunicada por escrito pela Ledyvas." },
      { t: "13. Suporte e atualizações", b: "A Ledyvas fornece o software, as atualizações e todo o suporte técnico e o atendimento ao cliente. A Ledyvas pode formar o pessoal do Distribuidor." },
      { t: "14. Confidencialidade", b: "Cada parte protege a informação não pública da outra: preços especiais, dados de clientes, roteiro do produto, números e condições do programa. A obrigação sobrevive à cessação." },
      { t: "15. Proteção de dados e conformidade fiscal", b: "Os dados de potenciais clientes e clientes recolhidos pelo Distribuidor são usados apenas para vender Ledyvas e partilhados com a Ledyvas, responsável pelo tratamento. Cada parte cumpre as suas obrigações fiscais no seu país; o Distribuidor declara a comissão como rendimento próprio e não representa a Ledyvas perante autoridades sem autorização expressa." },
      { t: "16. Duração e cessação", b: "O contrato tem uma duração estrita de um (1) ano desde a assinatura e não se renova automaticamente. No fim do período, a Ledyvas avaliará o desempenho do Distribuidor e reserva-se o direito de alterar o preço da adesão, as percentagens de comissão e os termos gerais para o período anual seguinte; sessenta (60) dias antes do vencimento comunicará se oferece renovação e em que termos. Como referência do critério de desempenho: se o Distribuidor concretizou quinze (15) ou mais vendas de licenças no período, a Ledyvas oferece a renovação com a adesão bonificada, sem custo; se não concretizou nenhuma venda no período, o contrato termina automaticamente no vencimento e o código é desativado sem necessidade de aviso; nos casos intermédios, a Ledyvas oferece a renovação ao preço de adesão em vigor nesse momento. Qualquer das partes pode terminar antes com aviso escrito de 30 dias, sem justa causa. A Ledyvas pode terminar de imediato por violação das cláusulas 5, 11 ou 12. Ao terminar, o Distribuidor deixa de usar a marca e de vender; as licenças já vendidas a clientes finais mantêm-se válidas e com suporte da Ledyvas; as comissões já vencidas e não revertidas são pagas à taxa original." },
      { t: "17. Sem sociedade nem vínculo laboral", b: "Este contrato não cria sociedade, franquia, agência com poder de representação nem vínculo laboral. O Distribuidor pode distribuir outros produtos, mesmo concorrentes, salvo acordo expresso em contrário." },
      { t: "18. Lei aplicável e litígios", b: "O presente contrato rege-se pelo direito da República Dominicana, em particular pelo Código Civil, pelo Código de Comércio e pela Lei n.º 126-02 sobre Comércio Eletrónico, Documentos e Assinaturas Digitais. Fica expressamente excluída a aplicação da Convenção das Nações Unidas sobre os Contratos de Compra e Venda Internacional de Mercadorias (Viena, 1980). As partes tentarão resolver qualquer divergência de boa-fé; não o conseguindo, submetem-se exclusivamente aos tribunais competentes da República Dominicana, renunciando expressamente a qualquer outro foro ou jurisdição que possa ser aplicável, seja qual for o domicílio ou a nacionalidade da outra parte." },
      { t: "19. Assinatura eletrónica", b: "Ao marcar a caixa de aceitação e escrever o nome completo do representante legal, o Distribuidor dá o consentimento e assina o presente contrato nos termos da Lei n.º 126-02 sobre Comércio Eletrónico, Documentos e Assinaturas Digitais, com o mesmo valor legal de uma assinatura manuscrita. A Ledyvas regista a data, a hora e o endereço IP como prova." }
    ]
  };

  var BY_ROLE = { distribuidor: DISTRIBUIDOR };

  window.ContratoTexto = {
    role: function () { return "distribuidor"; },
    title: function (role, lang) { return (TITLES[this.role(role)][lang] || TITLES[this.role(role)].es); },
    meta: function (lang) { return META[lang] || META.es; },
    parties: function (role, lang) { var m = PARTIES[this.role(role)]; return m[lang] || m.es; },
    clauses: function (role, lang) { var m = BY_ROLE[this.role(role)]; return m[lang] || m.es; }
  };
})();
